select x.id as run_id,x.race_id,x.horse_ref,x.horse_name,x.record_role,r.race_date,r.track,r.race_no,r.race_type,r.source_ref,r.source_checked_at,r.created_at as race_created_at,r.updated_at as race_updated_at,x.created_at as run_created_at,x.updated_at as run_updated_at from public.jra_lab_runs x join public.jra_lab_races r on r.id=x.race_id where x.id='c7a36ac8-f044-4f05-ab97-e616df44a459'::uuid;
